"use client"

import React from 'react'
import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import { 
  LayoutDashboard, 
  Radio, 
  Microscope, 
  LineChart, 
  Sprout, 
  Cpu, 
  Camera, 
  Bell, 
  FileText, 
  Settings, 
  LogOut 
} from 'lucide-react'
import { cn } from '@/lib/utils'

const navItems = [
  { label: 'Dashboard', icon: LayoutDashboard, href: '/dashboard', emoji: '📊' },
  { label: 'Sensor Realtime', icon: Radio, href: '/sensor', emoji: '📡' },
  { label: 'Diagnosa', icon: Microscope, href: '/diagnosa', emoji: '🔬' },
  { label: 'Riwayat Data', icon: LineChart, href: '/riwayat', emoji: '📈' },
  { label: 'Lahan Saya', icon: Sprout, href: '/lahan', emoji: '🌾' },
  { label: 'Perangkat IoT', icon: Cpu, href: '/iot', emoji: '🔌' },
  { label: 'Kamera', icon: Camera, href: '/camera', emoji: '📷' },
  { label: 'Notifikasi', icon: Bell, href: '/notifikasi', emoji: '🔔', badge: '2' },
  { label: 'Laporan', icon: FileText, href: '/laporan', emoji: '📄' },
  { label: 'Pengaturan', icon: Settings, href: '/settings', emoji: '⚙️' },
]

const devices = [
  { name: 'Sensor Lahan A', status: 'online' },
  { name: 'Sensor Lahan B', status: 'online' },
  { name: 'Sensor Lahan C', status: 'offline' },
]

export default function Sidebar() {
  const pathname = usePathname()
  const router = useRouter()

  const handleLogout = () => {
    localStorage.removeItem('TOKEN')
    router.push('/login')
  }

  return (
    <aside className="fixed left-0 top-0 h-screen w-[220px] bg-[#0a0f0a] border-r border-[#1e2e1e] flex flex-col z-50 dark-scroll overflow-y-auto">
      {/* LOGO */}
      <div className="p-6 border-b border-[#1e2e1e]">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-tsGreen rounded-lg flex items-center justify-center font-display font-bold text-tsBackground text-xl">
            T
          </div>
          <div>
            <h1 className="font-display font-bold text-tsTextPrimary text-lg leading-tight">TaniSmart</h1>
            <p className="font-mono text-[10px] text-tsTextDim uppercase tracking-wider">IoT Nutrisi</p>
          </div>
        </div>
      </div>

      {/* NAV ITEMS */}
      <div className="flex-1 py-6 px-3">
        <p className="font-mono text-[10px] text-tsTextDim px-3 mb-4 uppercase tracking-widest">Menu</p>
        <nav className="space-y-1">
          {navItems.map((item) => {
            const isActive = pathname === item.href
            return (
              <Link 
                key={item.href} 
                href={item.href}
                className={cn(
                  "flex items-center justify-between px-3 py-2 rounded-xl transition-all group",
                  isActive 
                    ? "bg-tsGreen/10 text-tsGreen border border-tsGreen/20" 
                    : "text-tsTextMuted hover:text-tsTextPrimary hover:bg-[#1e2e1e]"
                )}
              >
                <div className="flex items-center gap-3">
                  <span className="text-sm">{item.emoji}</span>
                  <span className="text-sm font-medium">{item.label}</span>
                </div>
                {item.badge && (
                  <span className="bg-tsRed text-white text-[10px] font-bold px-1.5 py-0.5 rounded-full">
                    {item.badge}
                  </span>
                )}
              </Link>
            )
          })}
        </nav>
      </div>

      {/* DEVICE STATUS */}
      <div className="p-6 border-t border-[#1e2e1e]">
        <p className="font-mono text-[10px] text-tsTextDim mb-4 uppercase tracking-widest">Perangkat</p>
        <div className="space-y-3">
          {devices.map((device) => (
            <div key={device.name} className="flex items-center justify-between">
              <span className="text-xs text-tsTextMuted font-mono">{device.name}</span>
              <div className={cn(
                "w-1.5 h-1.5 rounded-full",
                device.status === 'online' ? "bg-tsGreen animate-pulse-dot" : "bg-tsTextDim"
              )} />
            </div>
          ))}
        </div>
      </div>

      {/* LOGOUT */}
      <button 
        onClick={handleLogout}
        className="p-6 text-tsTextMuted hover:text-tsRed flex items-center gap-3 transition-colors text-sm font-medium border-t border-[#1e2e1e]"
      >
        <LogOut className="w-4 h-4" />
        Keluar
      </button>
    </aside>
  )
}